/**
 * The Generate place's acceptance, in the real app in Chrome. With Lato
 * loaded: three accented letters the face already has are generated by the
 * procedural strategy as a holdout test and scored against the face's own;
 * then the recorded Latin holdout run is replayed, its candidates are
 * labelled as recorded with their model names, one is accepted, the project
 * gains a revision, and the Studio opens that glyph.
 *
 * Nothing here calls a model. The recorded sheets are real saved output.
 */
import path from "node:path";
import type { Locator, Page } from "playwright-core";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { type AppSession, FIXTURE_FONTS, startApp } from "./support/app";
import { PORTS } from "./support/ports";
import { NARROW, SETTLE_MS, WIDE } from "./support/screen";

const LATO = path.join(FIXTURE_FONTS, "Lato-Regular.ttf");
const VECTOR_RUN = "2026-11-10-latin-holdout#vector-model";
const IMAGE_RUN = "2026-11-10-latin-holdout#image-model";
const VECTOR_MODEL = "ideogram/vector/text-to-vector";
const IMAGE_MODEL = "openai/gpt-image-2.6/flare/edit";

const AGREEMENT = /^Agreement (0\.\d\d|1\.00) with the face's own glyph/;
const BUILT_BY_RULE = /Built by rule on this machine/;
const RECORDED = /Recorded run, replayed\. Not live model output/;
const NO_REVISIONS = /1 font, 0 revisions/;
const ONE_REVISION = /1 font, 1 revision\b/;
const TWO_REVISIONS = /1 font, 2 revisions/;
const SECOND_ATTEMPT = /attempt 2/;
const REGENERATED = /Regenerated uni00E8 at/;
const CAPITAL_R = /U\+0052 LATIN CAPITAL LETTER R/;
const PROCEDURAL = "Procedural";
const RECORDED_STRATEGY = "Recorded run";
const VECTOR_STRATEGY = "Vector model";
const ONE_RUN_TAKES = /One run takes 24 characters/;
const NOT_A_CHARGE =
  /An estimate from the price fal listed on 10 November 2026, not a charge/;
const KEY_IN_MEMORY = /Kept in memory for this session only/;
const NONE_MADE = /No candidate was made for 3 of 3 targets/;
const NO_RULE_FOR_ANY =
  /No rule can build any of the 164 missing characters from glyphs the face has\. Choose a strategy that draws\./;
const REFERENCE_SHEET = /^Style reference sheet/;
const STAGE_COUNT = 9;

const candidates = (page: Page) => page.locator("li.ty-generate-candidate");

/** The agreement score each candidate on the board prints, as numbers. */
const agreements = async (page: Page): Promise<number[]> => {
  const scores: number[] = [];
  for (const cell of await candidates(page).all()) {
    const line = cell.locator(".ty-generate-agreement");
    // textContent, since the label is printed in capitals by the stylesheet.
    expect(await line.textContent()).toMatch(AGREEMENT);
    scores.push(Number(await line.getAttribute("data-agreement")));
  }
  return scores;
};

const stageStatuses = (page: Page) =>
  page
    .getByRole("list", { name: "Stages of the run" })
    .locator("li")
    .evaluateAll((rows) =>
      rows.map((row) => row.getAttribute("data-status") ?? "")
    );

const replay = async (page: Page, run: string, model: string) => {
  await page
    .getByRole("combobox", { name: "Recorded run to replay" })
    .selectOption(run);
  await page.getByRole("button", { name: "Replay the recorded run" }).click();
  await expect
    .poll(() => page.locator("[data-run-source]").innerText())
    .toContain(model);
  await expect.poll(() => candidates(page).count()).toBe(6);
};

describe("Generate in Chrome", () => {
  let app: AppSession;
  let page: Page;
  let places: Locator;

  /** A picture of the whole screen at one width, then back to the working size. */
  const shoot = async (name: string, width: number, height: number) => {
    await resize({ height, width });
    await app.screenshot(name);
    await resize(WIDE);
  };

  /** Changes the viewport and waits for the page to be drawn at the new size. */
  const resize = async (size: { height: number; width: number }) => {
    await page.setViewportSize(size);
    await page.evaluate(
      () =>
        new Promise<void>((resolve) => {
          requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
        })
    );
    await page.waitForTimeout(SETTLE_MS);
  };

  beforeAll(async () => {
    app = await startApp({ port: PORTS.generate, ...WIDE });
    ({ page } = app);
    places = page.getByRole("navigation", { name: "Places" });
    await places.getByRole("link", { name: "Import" }).click();
    await page.getByLabel("Add font files").setInputFiles(LATO);
    await page
      .getByRole("cell", { name: "Lato-Regular.ttf" })
      .first()
      .waitFor();
    await places.getByRole("link", { name: "Generate" }).click();
  });

  afterAll(async () => {
    await app.close();
  });

  it("generates three accented letters by rule as a holdout test and scores each", async () => {
    await page.getByRole("textbox", { name: "Characters" }).fill("é è ñ");
    const targets = page.getByRole("table", {
      name: "Targets of this request and what each depends on",
    });
    await expect.poll(() => targets.locator("tbody tr").count()).toBe(3);
    expect(await targets.innerText()).toContain("Holdout test");
    expect(await targets.innerText()).toContain("U+0301");
    await page
      .getByRole("table", { name: "What was measured from Lato Regular" })
      .waitFor();
    await page.getByRole("img", { name: REFERENCE_SHEET }).waitFor();
    expect(
      await page
        .getByRole("radio", { exact: true, name: PROCEDURAL })
        .isChecked()
    ).toBe(true);
    await app.screenshot("generate-e2e-1-request");

    await page.getByRole("button", { name: "Generate 3 glyphs" }).click();
    await expect.poll(() => candidates(page).count()).toBe(3);
    const scores = await agreements(page);
    expect(scores).toHaveLength(3);
    for (const score of scores) {
      expect(score).toBeGreaterThan(0.8);
      expect(score).toBeLessThanOrEqual(1);
    }
    for (const cell of await candidates(page).all()) {
      expect(await cell.innerText()).toMatch(BUILT_BY_RULE);
      expect(await cell.innerText()).not.toContain("Recorded run");
      expect(await cell.getAttribute("data-status")).toBe("proposed");
    }
    const statuses = await stageStatuses(page);
    expect(statuses).toHaveLength(STAGE_COUNT);
    expect(statuses).not.toContain("failed");
    expect(statuses).not.toContain("waiting");
    expect(await page.getByText(NO_REVISIONS).count()).toBe(1);
    await shoot("generate-e2e-2-procedural-holdout", WIDE.width, 4200);
  });

  it("rejects one candidate, regenerates another, accepts what passed, and undo returns them to proposed", async () => {
    const cell = (key: string) => page.locator(`li[data-candidate="${key}"]`);
    await cell("u+00f1").getByRole("button", { name: "Reject ñ" }).click();
    await expect
      .poll(() => cell("u+00f1").getAttribute("data-status"))
      .toBe("rejected");

    await cell("u+00e8").getByRole("button", { name: "Regenerate è" }).click();
    await cell("u+00e8").getByText(SECOND_ATTEMPT).waitFor();
    expect(await cell("u+00e8").getAttribute("data-status")).toBe("proposed");
    await page.getByText(REGENERATED).waitFor();
    expect(await candidates(page).count()).toBe(3);

    await page
      .getByRole("button", { name: "Accept everything that passed (2)" })
      .click();
    await page.getByText(TWO_REVISIONS).waitFor();
    expect(await cell("u+00e9").getAttribute("data-status")).toBe("accepted");
    expect(await cell("u+00e8").getAttribute("data-status")).toBe("accepted");
    expect(await cell("u+00f1").getAttribute("data-status")).toBe("rejected");

    // A candidate is accepted only while its revision is applied.
    const status = page.locator(".ty-masthead-status");
    await status.getByRole("button", { name: "Undo" }).click();
    await status.getByRole("button", { name: "Undo" }).click();
    await page.getByText(NO_REVISIONS).waitFor();
    expect(await cell("u+00e9").getAttribute("data-status")).toBe("proposed");
    expect(await cell("u+00e8").getAttribute("data-status")).toBe("proposed");
    expect(await cell("u+00f1").getAttribute("data-status")).toBe("rejected");
  });

  it("replays the recorded Latin holdout run, accepts a candidate and opens it in the Studio", async () => {
    // Choose the recorded run strategy from the keyboard: three rows down.
    await page.getByRole("radio", { exact: true, name: PROCEDURAL }).focus();
    await page.keyboard.press("ArrowDown");
    await page.keyboard.press("ArrowDown");
    await page.keyboard.press("ArrowDown");
    expect(
      await page
        .getByRole("radio", { exact: true, name: RECORDED_STRATEGY })
        .isChecked()
    ).toBe(true);

    // The image model's sheet is a picture: decoded and traced in the browser.
    await replay(page, IMAGE_RUN, IMAGE_MODEL);
    for (const cell of await candidates(page).all()) {
      const text = await cell.innerText();
      expect(text).toMatch(RECORDED);
      expect(text).toContain(IMAGE_MODEL);
    }
    const traced = await agreements(page);
    await shoot("generate-e2e-3-recorded-image-model", WIDE.width, 5600);

    // The vector model's sheet is SVG: its own curves become the outlines.
    await replay(page, VECTOR_RUN, VECTOR_MODEL);
    for (const cell of await candidates(page).all()) {
      const text = await cell.innerText();
      expect(text).toMatch(RECORDED);
      expect(text).toContain(VECTOR_MODEL);
      expect(text).toContain("Not reported by the provider");
    }
    const drawn = await agreements(page);
    for (const score of [...traced, ...drawn]) {
      expect(score).toBeGreaterThan(0.5);
      expect(score).toBeLessThan(1);
    }
    console.info(
      `Agreement with Lato: image model ${traced.join(" ")}, vector model ${drawn.join(" ")}`
    );
    expect(await stageStatuses(page)).not.toContain("failed");
    await shoot("generate-e2e-4-recorded-vector-model", WIDE.width, 5600);

    // Accept one: it becomes a revision, and only then leaves the dotted frame.
    const capitalR = page.locator('li[data-candidate="u+0052"]');
    expect(await capitalR.getAttribute("data-status")).toBe("proposed");
    await capitalR.getByRole("button", { name: "Accept R" }).click();
    await expect
      .poll(() => capitalR.getAttribute("data-status"))
      .toBe("accepted");
    await page.getByText(ONE_REVISION).waitFor();
    await capitalR.scrollIntoViewIfNeeded();
    await app.screenshot("generate-e2e-5-accepted");
    // The same screen at phone width: the request, then the board.
    await resize(NARROW);
    await page.locator("main").evaluate((main) => main.scrollTo({ top: 0 }));
    await app.screenshot("generate-e2e-6-narrow-request");
    await capitalR.scrollIntoViewIfNeeded();
    await app.screenshot("generate-e2e-6-narrow-candidate");
    await resize(WIDE);

    // The Studio opens the accepted glyph.
    await capitalR.getByRole("link", { name: "Open R in the Studio" }).click();
    await page.getByRole("application").waitFor();
    await page.getByText(CAPITAL_R).waitFor();
    await app.screenshot("generate-e2e-7-studio");

    // Back in Generate the run is still on the board, with its decision.
    await places.getByRole("link", { name: "Generate" }).click();
    await expect.poll(() => candidates(page).count()).toBe(6);
    expect(
      await page
        .locator('li[data-candidate="u+0052"]')
        .getAttribute("data-status")
    ).toBe("accepted");

    expect(app.errors).toEqual([]);
  });

  it("plans what a writing system and a language lack, and says why a model cannot run", async () => {
    const strategy = (name: string) =>
      page.locator(".ty-generate-strategy").filter({ hasText: name });
    // A strategy that draws is asked for the missing characters as they come.
    await strategy(VECTOR_STRATEGY).click();
    const targets = page.getByRole("table", {
      name: "Targets of this request and what each depends on",
    });

    // A language: what Hindi needs and Lato lacks.
    await page.getByRole("radio", { name: "Language" }).check({ force: true });
    await page
      .getByRole("combobox", { name: "Missing for the language" })
      .selectOption("hi");
    await expect.poll(() => targets.locator("tbody tr").count()).toBe(24);

    // A writing system: the first run's worth of Devanagari.
    await page
      .getByRole("radio", { name: "Writing system" })
      .check({ force: true });
    await page
      .getByRole("combobox", { name: "Missing in the writing system" })
      .selectOption({ label: "Devanagari" });
    await page.getByText(ONE_RUN_TAKES).waitFor();
    await expect.poll(() => targets.locator("tbody tr").count()).toBe(24);
    expect(await targets.innerText()).toContain("Missing from the face");

    // The vector model cannot run without a key, and says so. Nothing is called.
    const run = page.getByRole("button", { name: "Generate 24 glyphs" });
    expect(await run.isDisabled()).toBe(true);
    expect(await strategy(VECTOR_STRATEGY).innerText()).toContain(
      "No fal API key was supplied"
    );
    expect(
      await page.locator("[data-estimate]").getAttribute("data-estimate")
    ).toBe("0.24");
    await page.getByText(NOT_A_CHARGE).waitFor();
    await page.getByText(KEY_IN_MEMORY).waitFor();
    await app.screenshot("generate-e2e-8-model-unavailable");

    // A pasted key makes it available and is kept out of storage.
    await page.getByLabel("fal API key").fill("not-a-real-key");
    await expect.poll(() => run.isDisabled()).toBe(false);
    const stored = await page.evaluate(() =>
      JSON.stringify([{ ...localStorage }, { ...sessionStorage }])
    );
    expect(stored).not.toContain("not-a-real-key");
    await page.getByLabel("fal API key").fill("");
    await expect.poll(() => run.isDisabled()).toBe(true);

    // No rule builds Devanagari, so the procedural strategy is not asked for
    // it: the request says so before anything is run, and names the way out.
    await strategy(PROCEDURAL).click();
    // Said with the request, and again beside the run as the reason it cannot start.
    await page.getByText(NO_RULE_FOR_ANY).first().waitFor();
    await expect.poll(() => targets.count()).toBe(0);
    const nothing = page.getByRole("button", { name: "Generate 0 glyphs" });
    expect(await nothing.isDisabled()).toBe(true);

    // Typed, the same characters are asked for as typed, and the run says for
    // each that no rule builds it.
    await page
      .getByRole("radio", { name: "Typed list" })
      .check({ force: true });
    await page.getByRole("textbox", { name: "Characters" }).fill("कखग");
    await expect.poll(() => targets.locator("tbody tr").count()).toBe(3);
    await page.getByRole("button", { name: "Generate 3 glyphs" }).click();
    await page.getByText(NONE_MADE).waitFor();
    const unmade = page.getByRole("table", {
      name: "Targets no candidate was made for",
    });
    expect(await unmade.locator("tbody tr").count()).toBe(3);
    expect(await unmade.innerText()).toContain("No rule builds this glyph");
    expect(await candidates(page).count()).toBe(0);

    expect(app.errors).toEqual([]);
  });
});
